1	#include "fwd.h"
2	#include "fwd_kernel1.cuh"
3	#include "fwd_kernel2.cuh"
4	
5	// ==================== launch_fwd ====================
6	template <int D, bool HasStateIn, bool HasStateOut, bool StateFP32, bool IsVarlen>
7	void launch_fwd(
8	    cutlass::bfloat16_t const* q_ptr,
9	    cutlass::bfloat16_t const* k_ptr,
10	    cutlass::bfloat16_t const* v_ptr,
11	    cutlass::bfloat16_t const* g_bf16_ptr,
12	    cutlass::bfloat16_t const* beta_ptr,
13	    void const* initial_state_ptr,
14	    float scale,
15	    void* final_state_ptr,
16	    cutlass::bfloat16_t* out_ptr,
17	    void* workspace_ptr,
18	    int total_tiles,
19	    int T_total,
20	    int H,
21	    int N,
22	    int64_t const* cu_seqlens_ptr,
23	    float const* A_log_ptr,
24	    float const* dt_bias_ptr,
25	    float gate_scale,
26	    cudaStream_t stream
27	) {
28	    using BF16 = cutlass::bfloat16_t;
29	    constexpr int kInputStages = 3;
30	    constexpr int kOutputStages = 2;
31	    constexpr int CHUNK = 16;
32	
33	    using K1L = K1Layouts<D, CHUNK>;
34	    using K2L = K2Layouts<D, CHUNK>;
35	    using WS = WorkspaceSizes<CHUNK, D>;
36	
37	    // TMA layouts for Kernel 1
38	    using TMAQKLayout = typename K1L::TMAQKLayout;
39	    using TMAGLayout = typename K1L::TMAGLayout;
40	    using TMABetaSmemLayout = typename K1L::TMABetaSmemLayout;
41	    using TMAVOLayout = typename K1L::TMAVOLayout;
42	    using TMALMLayout = typename K1L::TMALMLayout;
43	    using TMAGTotalSmemLayout = typename K1L::TMAGTotalSmemLayout;
44	
45	    // TMA layouts for Kernel 2
46	    using TMAStateSmemLayout = typename K2L::TMAStateSmemLayout;
47	    using TMAFP32StateSmemLayout = typename K2L::TMAFP32StateSmemLayout;
48	
49	    // --- gmem layouts for original tensors
50	    auto gmem_layout = make_layout(make_shape(H, T_total, D), make_stride(D, D * H, 1));
51	    // 1D beta layout: [H*T] contiguous
52	    auto beta_gmem_layout = make_layout(make_shape(H * T_total));
53	    auto state_gmem_layout = make_layout(make_shape(N * H, D, D), LayoutRight{});
54	
55	    Tensor m_q   = make_tensor(make_gmem_ptr(q_ptr), gmem_layout);
56	    Tensor m_k   = make_tensor(make_gmem_ptr(k_ptr), gmem_layout);
57	    Tensor m_v   = make_tensor(make_gmem_ptr(v_ptr), gmem_layout);
58	    Tensor m_out = make_tensor(make_gmem_ptr(out_ptr), gmem_layout);
59	    Tensor m_beta = make_tensor(make_gmem_ptr<BF16>(beta_ptr), beta_gmem_layout);
60	
61	    // --- Workspace gmem layouts (separated arrays)
62	    int64_t n_ht = int64_t(H) * total_tiles;
63	    char* ws = reinterpret_cast<char*>(workspace_ptr);
64	    BF16*  ws_kd  = reinterpret_cast<BF16*>(ws);
65	    BF16*  ws_qd  = reinterpret_cast<BF16*>(ws + n_ht * WS::kKDecayed);
66	    BF16*  ws_kr  = reinterpret_cast<BF16*>(ws + n_ht * (WS::kKDecayed + WS::kQDecayed));
67	    float* ws_gt  = reinterpret_cast<float*>(ws + n_ht * (WS::kKDecayed + WS::kQDecayed + WS::kKRestored));
68	    BF16*  ws_inv = reinterpret_cast<BF16*>(ws + n_ht * (WS::kKDecayed + WS::kQDecayed + WS::kKRestored + WS::kGTotal));
69	    BF16*  ws_mqk = reinterpret_cast<BF16*>(ws + n_ht * (WS::kKDecayed + WS::kQDecayed + WS::kKRestored + WS::kGTotal + WS::kINV));
70	
71	    int* ws_tile_prefix = reinterpret_cast<int*>(ws + n_ht * WS::kPerTile);
72	
73	    auto ws_kd_gmem_layout = make_layout(make_shape(int(n_ht), CHUNK, D), LayoutRight{});
74	    auto ws_qd_gmem_layout = ws_kd_gmem_layout;
75	    auto ws_kr_gmem_layout = ws_kd_gmem_layout;
76	    auto ws_gt_gmem_layout = make_layout(make_shape(int(n_ht), D), LayoutRight{});
77	    auto ws_lm_gmem_layout = make_layout(make_shape(int(n_ht), CHUNK, CHUNK), LayoutRight{});
78	
79	    Tensor m_ws_kd  = make_tensor(make_gmem_ptr(ws_kd), ws_kd_gmem_layout);
80	    Tensor m_ws_qd  = make_tensor(make_gmem_ptr(ws_qd), ws_qd_gmem_layout);
81	    Tensor m_ws_kr  = make_tensor(make_gmem_ptr(ws_kr), ws_kr_gmem_layout);
82	    Tensor m_ws_gt  = make_tensor(make_gmem_ptr(ws_gt), ws_gt_gmem_layout);
83	    Tensor m_ws_inv = make_tensor(make_gmem_ptr(ws_inv), ws_lm_gmem_layout);
84	    Tensor m_ws_mqk = make_tensor(make_gmem_ptr(ws_mqk), ws_lm_gmem_layout);
85	
86	    // --- TMA descriptors for Kernel 1 (loads: q,k,beta; stores: workspace)
87	    auto tma_load_q    = make_tma_copy(SM90_TMA_LOAD{}, m_q, TMAQKLayout{});
88	    auto tma_load_k    = make_tma_copy(SM90_TMA_LOAD{}, m_k, TMAQKLayout{});
89	    auto tma_load_beta = make_tma_copy(SM90_TMA_LOAD{}, m_beta, TMABetaSmemLayout{});
90	
91	    Tensor m_g = make_tensor(make_gmem_ptr(g_bf16_ptr), gmem_layout);
92	    auto tma_load_g = make_tma_copy(SM90_TMA_LOAD{}, m_g, TMAQKLayout{});
93	
94	    auto dt_bias_gmem_layout = make_layout(make_shape(H, D), LayoutRight{});
95	    Tensor m_dt_bias = make_tensor(make_gmem_ptr(dt_bias_ptr), dt_bias_gmem_layout);
96	    auto tma_load_dt_bias = make_tma_copy(SM90_TMA_LOAD{}, m_dt_bias, TMAGTotalSmemLayout{});
97	
98	    auto tma_store_ws_kd  = make_tma_copy(SM90_TMA_STORE{}, m_ws_kd, TMAVOLayout{});
99	    auto tma_store_ws_qd  = make_tma_copy(SM90_TMA_STORE{}, m_ws_qd, TMAVOLayout{});
100	    auto tma_store_ws_kr  = make_tma_copy(SM90_TMA_STORE{}, m_ws_kr, TMAVOLayout{});
101	    auto tma_store_ws_gt  = make_tma_copy(SM90_TMA_STORE{}, m_ws_gt, TMAGTotalSmemLayout{});
102	    auto tma_store_ws_inv = make_tma_copy(SM90_TMA_STORE{}, m_ws_inv, TMALMLayout{});
103	    auto tma_store_ws_mqk = make_tma_copy(SM90_TMA_STORE{}, m_ws_mqk, TMALMLayout{});
104	
105	    // --- TMA descriptors for Kernel 2 (loads: v,beta,workspace; load/store: state,out)
106	    auto tma_load_v     = make_tma_copy(SM90_TMA_LOAD{}, m_v, TMAVOLayout{});
107	    auto tma_load_beta2 = make_tma_copy(SM90_TMA_LOAD{}, m_beta, TMABetaSmemLayout{});
108	
109	    auto tma_load_ws_kd  = make_tma_copy(SM90_TMA_LOAD{}, m_ws_kd, TMAVOLayout{});
110	    auto tma_load_ws_qd  = make_tma_copy(SM90_TMA_LOAD{}, m_ws_qd, TMAVOLayout{});
111	    auto tma_load_ws_kr  = make_tma_copy(SM90_TMA_LOAD{}, m_ws_kr, TMAVOLayout{});
112	    auto tma_load_ws_gt  = make_tma_copy(SM90_TMA_LOAD{}, m_ws_gt, TMAGTotalSmemLayout{});
113	    auto tma_load_ws_inv = make_tma_copy(SM90_TMA_LOAD{}, m_ws_inv, TMALMLayout{});
114	    auto tma_load_ws_mqk = make_tma_copy(SM90_TMA_LOAD{}, m_ws_mqk, TMALMLayout{});
115	
116	    auto tma_store_out = make_tma_copy(SM90_TMA_STORE{}, m_out, TMAVOLayout{});
117	
118	    // --- State TMA descriptors (conditional on HasStateIn/HasStateOut and StateFP32)
119	    auto make_state_tma = [&]() {
120	        if constexpr (StateFP32) {
121	            // FP32 state TMA descriptors
122	            auto m_initial_fp32 = make_tensor(
123	                make_gmem_ptr(static_cast<float const*>(initial_state_ptr)), state_gmem_layout);
124	            auto m_final_fp32 = make_tensor(
125	                make_gmem_ptr(static_cast<float*>(final_state_ptr)), state_gmem_layout);
126	            auto tma_load = make_tma_copy(SM90_TMA_LOAD{}, m_initial_fp32, TMAFP32StateSmemLayout{});
127	            auto tma_store = make_tma_copy(SM90_TMA_STORE{}, m_final_fp32, TMAFP32StateSmemLayout{});
128	            return cute::make_tuple(tma_load, tma_store);
129	        } else {
130	            // BF16 state TMA descriptors (or dummy for no-state)
131	            auto state_ptr_load = HasStateIn
132	                ? static_cast<BF16 const*>(initial_state_ptr)
133	                : reinterpret_cast<BF16 const*>(out_ptr);  // dummy, never used
134	            auto state_ptr_store = HasStateOut
135	                ? static_cast<BF16*>(final_state_ptr)
136	                : reinterpret_cast<BF16*>(out_ptr);  // dummy, never used
137	            auto m_init = make_tensor(make_gmem_ptr(state_ptr_load), state_gmem_layout);
138	            auto m_final = make_tensor(make_gmem_ptr(state_ptr_store), state_gmem_layout);
139	            auto tma_load = make_tma_copy(SM90_TMA_LOAD{}, m_init, TMAStateSmemLayout{});
140	            auto tma_store = make_tma_copy(SM90_TMA_STORE{}, m_final, TMAStateSmemLayout{});
141	            return cute::make_tuple(tma_load, tma_store);
142	        }
143	    };
144	    auto [tma_load_initial_state, tma_store_final_state] = make_state_tma();
145	
146	    // ===== Launch Kernel 1 (prepare) =====
147	#if BLOCK_LEVEL_K1 >= 0
148	    {
149	        constexpr int kK1Threads = 256;
150	        using SharedStorageK1T = SharedStorageK1<K1L>;
151	        int smem_size_k1 = sizeof(SharedStorageK1T);
152	
153	        auto kernel1 = _flash_kda_fwd_prepare<
154	            decltype(tma_load_q), decltype(tma_load_k),
155	            decltype(tma_load_beta),
156	            decltype(tma_load_g), decltype(tma_load_dt_bias),
157	            decltype(tma_store_ws_kd), decltype(tma_store_ws_qd), decltype(tma_store_ws_kr),
158	            decltype(tma_store_ws_gt), decltype(tma_store_ws_inv), decltype(tma_store_ws_mqk),
159	            CHUNK, D, kK1Threads, IsVarlen
160	        >;
161	
162	        cudaFuncSetAttribute(kernel1, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size_k1);
163	
164	        if constexpr (IsVarlen) {
165	            _flash_kda_build_tile_prefix<<<1, 32, 0, stream>>>(
166	                cu_seqlens_ptr, N, CHUNK, ws_tile_prefix);
167	        }
168	
169	        dim3 grid_k1(total_tiles, H);
170	        dim3 block_k1(kK1Threads);
171	
172	        kernel1<<<grid_k1, block_k1, smem_size_k1, stream>>>(
173	            tma_load_q, tma_load_k, tma_load_beta,
174	            tma_load_g, tma_load_dt_bias,
175	            tma_store_ws_kd, tma_store_ws_qd, tma_store_ws_kr,
176	            tma_store_ws_gt, tma_store_ws_inv, tma_store_ws_mqk,
177	            scale, T_total, H, N, cu_seqlens_ptr, total_tiles,
178	            A_log_ptr, gate_scale, ws_tile_prefix
179	        );
180	    }
181	#endif
182	
183	    // ===== Launch Kernel 2 (recurrence) =====
184	#if BLOCK_LEVEL_K2 >= 0
185	    {
186	        constexpr int kK2Threads = 32 * 2 + 128;
187	        using SharedStorageK2T = SharedStorageK2<K2L, kInputStages, kOutputStages>;
188	        int smem_size_k2 = sizeof(SharedStorageK2T);
189	
190	        auto kernel2 = _flash_kda_fwd_recurrence<
191	            decltype(tma_load_v), decltype(tma_load_beta2),
192	            decltype(tma_load_ws_kd), decltype(tma_load_ws_qd), decltype(tma_load_ws_kr),
193	            decltype(tma_load_ws_gt), decltype(tma_load_ws_inv), decltype(tma_load_ws_mqk),
194	            decltype(tma_load_initial_state),
195	            decltype(tma_store_final_state),
196	            decltype(tma_store_out),
197	            CHUNK, D, kInputStages, kOutputStages, kK2Threads,
198	            HasStateIn, HasStateOut, StateFP32, IsVarlen
199	        >;
200	
201	        cudaFuncSetAttribute(kernel2, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size_k2);
202	
203	        dim3 grid_k2(N, H);
204	        dim3 block_k2(kK2Threads);
205	
206	        kernel2<<<grid_k2, block_k2, smem_size_k2, stream>>>(
207	            tma_load_v, tma_load_beta2,
208	            tma_load_ws_kd, tma_load_ws_qd, tma_load_ws_kr,
209	            tma_load_ws_gt, tma_load_ws_inv, tma_load_ws_mqk,
210	            tma_load_initial_state,
211	            tma_store_final_state,
212	            tma_store_out,
213	            out_ptr, T_total, H, N, cu_seqlens_ptr, total_tiles
214	        );
215	    }
216	#endif
217	}
218	
219	// Explicit instantiations
220	#define INSTANTIATE_LAUNCH_FWD(D, HI, HO, FP32, VL) \
221	    template void launch_fwd<D, HI, HO, FP32, VL>( \
222	        cutlass::bfloat16_t const*, cutlass::bfloat16_t const*, \
223	        cutlass::bfloat16_t const*, cutlass::bfloat16_t const*, \
224	        cutlass::bfloat16_t const*, void const*, float, void*, \
225	        cutlass::bfloat16_t*, void*, int, int, int, int, \
226	        int64_t const*, float const*, float const*, float, cudaStream_t);
227	
228	#define INSTANTIATE_STATE_VARIANTS(VL) \
229	    INSTANTIATE_LAUNCH_FWD(128, true,  true,  false, VL) \
230	    INSTANTIATE_LAUNCH_FWD(128, true,  true,  true,  VL) \
231	    INSTANTIATE_LAUNCH_FWD(128, false, false, false, VL) \
232	    INSTANTIATE_LAUNCH_FWD(128, false, true,  false, VL) \
233	    INSTANTIATE_LAUNCH_FWD(128, true,  false, false, VL) \
234	    INSTANTIATE_LAUNCH_FWD(128, false, true,  true,  VL) \
235	    INSTANTIATE_LAUNCH_FWD(128, true,  false, true,  VL)
236	
237	INSTANTIATE_STATE_VARIANTS(true)   // varlen
238	INSTANTIATE_STATE_VARIANTS(false)  // non-varlen
